DROP TABLE IF EXISTS rental_device_import_batch;
DROP TABLE IF EXISTS rental_device;
DROP TABLE IF EXISTS rental_device_model;
DROP TABLE IF EXISTS rental_device_category;
CREATE TABLE rental_device_import_batch (id varchar(36) PRIMARY KEY,user_id bigint NOT NULL,request_json clob NOT NULL,preview_json clob NOT NULL,result_json clob,expires_at timestamp NOT NULL,creator varchar(64) DEFAULT '', create_time timestamp DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time timestamp DEFAULT CURRENT_TIMESTAMP, deleted boolean NOT NULL DEFAULT false, tenant_id bigint NOT NULL);
CREATE TABLE rental_device (id bigint AUTO_INCREMENT PRIMARY KEY,device_no varchar(64),legacy_device_no varchar(64),serial_number varchar(128),category_code varchar(32),equipment_model_code varchar(64),status varchar(32),warehouse_code varchar(64),purchase_amount int,enabled boolean,source_type varchar(32),source_biz_id bigint,source_item_id bigint,creator varchar(64) DEFAULT '', create_time timestamp DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time timestamp DEFAULT CURRENT_TIMESTAMP, deleted boolean NOT NULL DEFAULT false, tenant_id bigint NOT NULL,UNIQUE(tenant_id,device_no),UNIQUE(tenant_id,serial_number),CHECK(serial_number <> 'FAIL9999'));
CREATE TABLE rental_device_model (id bigint AUTO_INCREMENT PRIMARY KEY,category_id bigint,model_code varchar(64),model_name varchar(128),device_no_prefix varchar(64),next_sequence int,sort_order int,enabled boolean,lock_version int,creator varchar(64) DEFAULT '', create_time timestamp DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time timestamp DEFAULT CURRENT_TIMESTAMP, deleted boolean NOT NULL DEFAULT false, tenant_id bigint NOT NULL);
CREATE TABLE rental_device_category (id bigint AUTO_INCREMENT PRIMARY KEY,category_code varchar(32),category_name varchar(128),sort_order int,enabled boolean,lock_version int,creator varchar(64) DEFAULT '', create_time timestamp DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time timestamp DEFAULT CURRENT_TIMESTAMP, deleted boolean NOT NULL DEFAULT false, tenant_id bigint NOT NULL);
